            return null;
        }

        $snapshot = SettingsRevision::record(
            'upgrade_snapshot',
            self::GROUP,
            $stored,
            $stored,
            $userId,
            now()->addDays(self::SNAPSHOT_DAYS),
            ['schema' => AppearanceSettings::SCHEMA_VERSION],
        );

        $plan = $this->plan($stored);
        $target = $plan['target'];
        $now = now();
        $foreign = DB::table('settings')
            ->whereIn('key', array_keys($target))
            ->where('group', '!=', self::GROUP)
            ->pluck('key')
            ->all();

        foreach ($target as $key => $value) {
            if (in_array($key, $foreign, true)) {
                continue;
            }

            if (! array_key_exists($key, $stored)) {
                DB::table('settings')->insert(['key' => $key, 'value' => $value, 'group' => self::GROUP, 'created_at' => $now, 'updated_at' => $now]);
            } elseif ($stored[$key] !== $value) {
                DB::table('settings')->where('key', $key)->where('group', self::GROUP)->update(['value' => $value, 'updated_at' => $now]);
            }
        }

        $removed = array_keys(array_diff_key($stored, $target));

        if ($removed !== []) {
            DB::table('settings')->where('group', self::GROUP)->whereIn('key', $removed)->delete();
        }

        $revision = SettingsRevision::record(
            'upgrade_result',
            self::GROUP,
            $stored,
            SettingsRevision::rows(self::GROUP),
            $userId,
            null,
            array_diff_key($plan, ['target' => true]) + ['snapshot' => $snapshot],
        );

        return [
            'class' => $plan['class'],
            'theme' => $plan['theme'],
            'flavor' => $plan['flavor'],
            'snapshot' => $snapshot,
