    /**
     * Step 4: a key is untouched when it is absent or equals what the old code would have shown anyway.
     */
    private function untouched(array $stored, string $key, string $preset, string $master): bool
    {
        if (! array_key_exists($key, $stored)) {
            return true;
        }

        $sources = $this->sources();
        $candidates = [
            $sources['preset_values'][$preset][$key] ?? null,
            $sources['old_defaults'][$key] ?? null,
            $sources['example_sql_appearance_rows'][$key] ?? null,
            $sources['reset_default_theme_state'][$key] ?? null,
        ];

        if (isset($sources['masters'][$master]) && in_array($key, $sources['master_controlled_keys'], true)) {
            $candidates[] = $sources['masters'][$master][$key] ?? null;
        }

        foreach ($sources['fallbacks'] as $fallback) {
            $candidates[] = $fallback[$key] ?? null;
        }

        foreach ($candidates as $candidate) {
            if ($candidate !== null && $this->same($stored[$key], $candidate)) {
                return true;
            }
        }

        return false;
    }

    /**
     * Colours compare case-insensitively, '1'/'0'/'true'/'false' as booleans.
     */
    private function same(mixed $value, mixed $old): bool
    {
        $value = trim((string) $value);
        $old = trim((string) $old);

        if (preg_match('/^#[0-9a-f]{3,8}$/i', $value) && preg_match('/^#[0-9a-f]{3,8}$/i', $old)) {
            return strtolower($value) === strtolower($old);
        }

        $bool = fn (string $v): ?bool => match (strtolower($v)) {
            '1', 'true' => true,
            '0', 'false' => false,
            default => null,
        };

        if ($bool($value) !== null && $bool($old) !== null) {
            return $bool($value) === $bool($old);
        }

        return $value === $old;
    }

    /**
     * Customised sites keep their layout: preset/look keys they never stored keep the value the old code rendered.
     */
    private function keepOldLook(array $target, array $stored): array
    {
        $sources = $this->sources();

        foreach (array_unique(array_merge($sources['preset_controlled_keys'], $sources['master_controlled_keys'])) as $key) {
            if (! array_key_exists($key, $stored) && ! in_array($key, ThemeCatalog::COLOUR_KEYS, true)
                && ! in_array($key, ['theme', 'theme_preset'], true) && array_key_exists($key, $sources['old_defaults'])) {
                $target[$key] = (string) $sources['old_defaults'][$key];
            }
        }

        return $target;
    }

    private function canonicalMaster(string $master): string
    {
        return $this->sources()['legacy_master_ids'][$master] ?? $master;
    }

    /** The stored colour style when the site uses it: a valid style of a v2 theme id (else the id fixes the style). */
    private function publishedFlavor(array $stored, string $preset): ?string
