    /**
     * Whether the redesigned admin already published a look, a theme or a colour style on these rows (its Appearance
     * pages work before "Finish update"): a look or a theme the old admin did not have, or a colour style next to a v2
     * theme id. The old admin never stored any of them.
     */
    private function publishedBeforeUpdate(string $preset, ?string $flavor, string $master, bool $isMaster): bool
    {
        if ($master !== '' && ! $isMaster && array_key_exists($master, MasterExperienceCatalog::all())) {
            return true;
        }

        return ThemeCatalog::isThemeId($preset) && ($flavor !== null || ! array_key_exists($preset, ThemeCatalog::aliases()));
    }

    /**
     * The look's v2 settings: WP3's MasterExperienceCatalog when it carries apply_settings, else the frozen copy.
     *
     * @return array<string, string>
     */
    private function masterSettings(string $master): array
    {
        $live = MasterExperienceCatalog::find($master);
        $settings = is_array($live['apply_settings'] ?? null) ? $live['apply_settings'] : ($this->masterFallback()[$master]['apply_settings'] ?? []);

        return array_map('strval', array_filter($settings, 'is_scalar'));
    }

    /**
     * Upgrade policy of an old look: ['mode' => 'reapply'|'colours_only', 'alias', 'v2_theme'].
     */
    private function masterPolicy(string $master): ?array
    {
        if (method_exists(MasterExperienceCatalog::class, 'upgradePolicy')) {
            $rows = MasterExperienceCatalog::upgradePolicy();
            $row = $rows[$master] ?? null;

            foreach ($row === null ? $rows : [] as $candidate) {
                if (is_array($candidate) && ($candidate['master'] ?? null) === $master) {
                    $row = $candidate;
                }
            }

            if (is_array($row) && (isset($row['mode']) || isset($row['untouched_upgrade']))) {
                $mode = $row['mode'] ?? (str_starts_with(strtolower((string) $row['untouched_upgrade']), 'colours only') ? 'colours_only' : 'reapply');

                return ['mode' => $mode, 'alias' => $row['alias'] ?? null, 'v2_theme' => $row['v2_theme'] ?? null];
            }
        }

        return $this->masterFallback()[$master] ?? null;
    }

    private function masterFallback(): array
    {
        return json_decode(self::MASTER_UPGRADE_FALLBACK, true, 512, JSON_THROW_ON_ERROR);
    }

    private function sources(): array
    {
        return $this->sources ??= json_decode(self::FACTORY_SOURCES, true, 512, JSON_THROW_ON_ERROR);
    }
};
